sys_script_include.script:
function MakeJavaScriptIdentifier(strInput)
{
	strInput = GetStringValue(strInput);
	strInput = strInput.trim();

	if (IsValidJavaScriptIdentifier(strInput) == true)
	{
		return strInput;
	}

	var strIdentifier = MakePascalCase(strInput);

	if (strIdentifier == '')
	{
		return false;
	}

	// If the first character is a digit, replace leading digits with words
	var digitWords = ['Zero', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine'];
	var i = 0;
	var prefix = '';
	while (i < strIdentifier.length && strIdentifier.charAt(i) >= '0' && strIdentifier.charAt(i) <= '9')
	{
		var digit = GetIntegerValue(strIdentifier.charAt(i));
		prefix += digitWords[digit];
		i++;
	}

	if (prefix.length > 0)
	{
		// Append the rest of the string as-is (without converting digits inside)
		// But if the next character after digits is a letter and prefix ends with a letter,
		// and the next character is lowercase, keep it as is (for camelCase after digits)
		// So just append substring from i without changing case
		strIdentifier = prefix + strIdentifier.substring(i);
	}

	return strIdentifier;
}
